name: Notify Dev Channel
on:
  push:
    branches: [ master ]
    paths: [ 'src/**' ]

jobs:
  notify:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout code
        uses: actions/checkout@v4
        with:
          fetch-depth: 2

      - name: Extract PR number from commit message
        id: extract_pr
        run: |
          COMMIT_MESSAGE=$(git log --format=%B -n 1)
          echo "commit_message=$COMMIT_MESSAGE" >> $GITHUB_ENV

          # Extract PR number using regex
          PR_NUMBER=$(echo "$COMMIT_MESSAGE" | grep -oE 'Merge pull request #[0-9]+' | grep -oE '[0-9]+' | head -1)
          if [ -n "$PR_NUMBER" ]; then
            echo "pr_number=$PR_NUMBER" >> $GITHUB_ENV
          fi

      - name: Get PR details
        if: env.pr_number != ''
        id: get_pr
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: parseInt('${{ env.pr_number }}')
            });

            // Extract issue numbers from PR body
            const issueRegex = /(?:Closes|Fixes|Resolves)\s+#(\d+)/gi;
            let match;
            const issues = [];
            while ((match = issueRegex.exec(pr.body)) !== null) {
              issues.push(match[1]);
            }

            // Store results
            core.setOutput('pr_title', pr.title);
            core.setOutput('pr_body', pr.body);
            core.setOutput('pr_url', pr.html_url);
            core.setOutput('issue_numbers', issues.join(','));
            core.setOutput('author', pr.user.login);

      - name: Post comment to PR
        if: env.pr_number != '' && env.pr_number != null
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr_number = process.env.pr_number;
            const pr_title = process.env.pr_title;
            const pr_body = process.env.pr_body;
            const pr_url = process.env.pr_url;
            const issue_numbers = process.env.issue_numbers;
            const author = process.env.author;

            const commentBody = `## 🧪 Your changes are now in the dev channel!

Your PR has been merged to master and is available for testing in the **dev channel**.

**Test your changes before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: \`uvx ha-mcp-dev\``;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: parseInt(pr_number),
              body: commentBody
            });

      - name: Post comment to linked issues
        if: env.pr_number != '' && env.pr_number != null && steps.get_pr.outputs.issue_numbers != ''
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr_number = process.env.pr_number;
            const pr_title = process.env.pr_title;
            const pr_url = process.env.pr_url;
            const author = process.env.author;
            const issueNumbers = process.env.issue_numbers.split(',');

            const commentBody = `## ✅ This issue has been addressed in the dev channel!

A fix for this issue has been merged to master (PR #${pr_number}) and is available for testing...`;

            for (const issueNumber of issueNumbers) {
              try {
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: parseInt(issueNumber.trim()),
                  body: commentBody
                });
              } catch (error) {
                console.log(`Failed to comment on issue ${issueNumber}:`, error.message);
              }
            }
